"use client"

import * as React from "react"
import * as MenuPrimitive from "@radix-ui/react-dropdown-menu"

import { cn } from "@/lib/utils"

function DropdownMenu(props: React.ComponentProps<typeof MenuPrimitive.Root>) {
  return <MenuPrimitive.Root data-slot="dropdown-menu" {...props} />
}

function DropdownMenuTrigger(props: React.ComponentProps<typeof MenuPrimitive.Trigger>) {
  return <MenuPrimitive.Trigger data-slot="dropdown-menu-trigger" {...props} />
}

function DropdownMenuGroup(props: React.ComponentProps<typeof MenuPrimitive.Group>) {
  return <MenuPrimitive.Group data-slot="dropdown-menu-group" {...props} />
}

function DropdownMenuRadioGroup(props: React.ComponentProps<typeof MenuPrimitive.RadioGroup>) {
  return <MenuPrimitive.RadioGroup data-slot="dropdown-menu-radio-group" {...props} />
}

function DropdownMenuSub(props: React.ComponentProps<typeof MenuPrimitive.Sub>) {
  return <MenuPrimitive.Sub data-slot="dropdown-menu-sub" {...props} />
}

/**
 * A list of words on the popover panel, hung from its trigger on a leader line. The word
 * you point at is marked with the highlighter; the words arrive in turn.
 */
function DropdownMenuContent({
  className,
  align = "start",
  sideOffset = 27, /* --db-space-5: the leader is this long */
  collisionPadding = 20,
  style,
  ...props
}: React.ComponentProps<typeof MenuPrimitive.Content>) {
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Content
        data-slot="dropdown-menu-content"
        align={align}
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        style={{ "--db-pop-gap": `${sideOffset}px`, ...style } as React.CSSProperties}
        className={cn("db-pop db-menu", className)}
        {...props}
      />
    </MenuPrimitive.Portal>
  )
}

/** A destructive item says so in its words ("Delete Halden for good"); it is never red. */
function DropdownMenuItem({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<typeof MenuPrimitive.Item> & { variant?: "default" | "destructive" }) {
  return <MenuPrimitive.Item data-slot="dropdown-menu-item" data-variant={variant} className={cn("db-menu-item", className)} {...props} />
}

/** Checked, the sentence turns to the expression italic. Screen readers get aria-checked. */
function DropdownMenuCheckboxItem({ className, ...props }: React.ComponentProps<typeof MenuPrimitive.CheckboxItem>) {
  return <MenuPrimitive.CheckboxItem data-slot="dropdown-menu-checkbox-item" className={cn("db-menu-item", className)} {...props} />
}

function DropdownMenuRadioItem({ className, ...props }: React.ComponentProps<typeof MenuPrimitive.RadioItem>) {
  return <MenuPrimitive.RadioItem data-slot="dropdown-menu-radio-item" className={cn("db-menu-item", className)} {...props} />
}

function DropdownMenuLabel({ className, ...props }: React.ComponentProps<typeof MenuPrimitive.Label>) {
  return <MenuPrimitive.Label data-slot="dropdown-menu-label" className={cn("db-menu-label", className)} {...props} />
}

function DropdownMenuSeparator({ className, ...props }: React.ComponentProps<typeof MenuPrimitive.Separator>) {
  return <MenuPrimitive.Separator data-slot="dropdown-menu-separator" className={cn("db-menu-sep", className)} {...props} />
}

/**
 * Shortcut keys, each drawn as a base `db-kbd` ring. A string of one word splits into
 * its characters ("⌘D" is two keys); a string with spaces splits on them ("Shift Tab").
 */
function DropdownMenuShortcut({ className, children, ...props }: React.ComponentProps<"span">) {
  const keys = typeof children === "string" ? (children.includes(" ") ? children.split(" ") : [...children]) : null
  return (
    <span data-slot="dropdown-menu-shortcut" className={cn("db-menu-keys", className)} {...props}>
      {keys ? keys.map((k, i) => <kbd key={i} className="db-kbd">{k}</kbd>) : children}
    </span>
  )
}

/** Opens something, so it carries the one → glyph. */
function DropdownMenuSubTrigger({ className, ...props }: React.ComponentProps<typeof MenuPrimitive.SubTrigger>) {
  return <MenuPrimitive.SubTrigger data-slot="dropdown-menu-sub-trigger" className={cn("db-menu-item db-menu-sub", className)} {...props} />
}

function DropdownMenuSubContent({ className, sideOffset = 2, alignOffset = -8, ...props }: React.ComponentProps<typeof MenuPrimitive.SubContent>) {
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.SubContent data-slot="dropdown-menu-sub-content" sideOffset={sideOffset} alignOffset={alignOffset} className={cn("db-pop db-menu", className)} {...props} />
    </MenuPrimitive.Portal>
  )
}

export {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuItem,
  DropdownMenuCheckboxItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubTrigger,
  DropdownMenuSubContent,
}

@layer components {
  /* ── db-menu ── a list of words on the popover panel (db-pop, from popover.css: the
     leader, the in and out); the one you point at is marked with the highlighter.
     Radix moves the highlight (data-highlighted) with the pointer and the arrow keys.
     Dropdown menu, context menu and menubar all wear it. */
  .db-pop.db-menu { padding: var(--db-space-2) 0; min-width: 14rem; }
  .db-pop.db-menu > * { animation: db-arrive var(--db-moderato) var(--db-exhale) backwards; animation-delay: calc((sibling-index() - 1) * var(--db-arpeggio)); }
  .db-pop.db-menu[data-state="closed"] > * { animation: none; }

  .db-menu-item {
    position: relative; display: flex; justify-content: space-between; align-items: baseline; gap: var(--db-space-6);
    margin: 0; padding: 0.34em var(--db-space-5); cursor: pointer; user-select: none; outline: 0;
    color: var(--db-graphite);
    background: linear-gradient(var(--db-mark), var(--db-mark)) no-repeat 100% 0 / 0% 100%;
    /* The colour flips with the first frames of the stroke and back after the last, as the link's does, so the words are never pale on yellow. */
    transition: background-size var(--db-allegro) var(--db-exhale), background-position 0s, color 0s linear var(--db-allegro);
  }
  .db-menu-item:is([data-highlighted], .db-menu-sub[data-state="open"]) { background-position: 0 0; background-size: 100% 100%; color: var(--db-on-mark); transition-delay: 0s; }
  .db-menu-item:is([dir="rtl"], [dir="rtl"] *) { background-position: 0 0; }
  .db-menu-item:is([dir="rtl"], [dir="rtl"] *):is([data-highlighted], .db-menu-sub[data-state="open"]) { background-position: 100% 0; }

  /* Checked, a sentence is yours: the expression italic. */
  .db-menu-item:is([data-state="checked"]) {
    font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * 1em); color: var(--db-ink);
    line-height: calc(var(--db-p-lh) / var(--db-expression-scale)); padding-block: calc(0.34em / var(--db-expression-scale)); /* the row keeps its height */
  }
  .db-menu-item[data-state="checked"][data-highlighted] { color: var(--db-on-mark); }

  /* A destructive item says so in its words; it only sits a little heavier. Red is for errors. */
  .db-menu-item[data-variant="destructive"] { font-weight: 500; color: var(--db-ink); }
  .db-menu-item[data-variant="destructive"][data-highlighted] { color: var(--db-on-mark); }

  .db-menu-item[data-disabled] { color: var(--db-pencil); opacity: 0.55; cursor: not-allowed; pointer-events: none; }

  /* Only a sub-trigger opens something, so only it carries the arrow. */
  .db-menu-sub::after { content: "→" / ""; font-size: 0.85em; color: var(--db-pencil); }
  .db-menu-sub:is([dir="rtl"], [dir="rtl"] *)::after { content: "←" / ""; }
  .db-menu-sub:is([data-highlighted], [data-state="open"])::after { color: inherit; }

  .db-menu-keys { display: inline-flex; align-items: baseline; gap: var(--db-space-1); font-size: var(--db-pp); color: var(--db-pencil); font-variant-numeric: tabular-nums; }
  .db-menu-item[data-highlighted] .db-menu-keys, .db-menu-item[data-highlighted] .db-kbd { color: inherit; }

  .db-menu-label { padding: var(--db-space-2) var(--db-space-5) var(--db-space-1); font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-pencil); }
  .db-menu-sep { height: var(--db-hairline); margin-block: var(--db-space-2); background: var(--db-rule); }
}
